{"command":"cat <<'EOF' > src/ast.rs
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Span {
    pub start: usize,
    pub end: usize,
    pub start_line: usize,
    pub start_col: usize,
    pub end_line: usize,
    pub end_col: usize,
}

impl Span {
    pub fn dummy() -> Self {
        Span {
            start: 0,
            end: 0,
            start_line: 1,
            start_col: 1,
            end_line: 1,
            end_col: 1,
        }
    }
}

#[derive(Debug, Clone)]
pub struct Ident {
    pub name: String,
    pub span: Span,
}

#[derive(Debug, Clone)]
pub enum Expr {
    Ident(Ident),
    Literal(Span),
    String(Vec<StringPart>, Span),
    List(Vec<Expr>, Span),
    AttrSet {
        is_rec: bool,
        bindings: Vec<Binding>,
        span: Span,
    },
    Select {
        expr: Box<Expr>,
        path: Vec<Ident>,
        default: Option<Box<Expr>>,
        span: Span,
    },
    HasAttr {
        expr: Box<Expr>,
        path: Vec<Ident>,
        span: Span,
    },
    Apply {
        func: Box<Expr>,
        arg: Box<Expr>,
        span: Span,
    },
    Binary {
        op: String,
        left: Box<Expr>,
        right: Box<Expr>,
        span: Span,
    },
    Unary {
        op: String,
        expr: Box<Expr>,
        span: Span,
    },
    If {
        cond: Box<Expr>,
        then_branch: Box<Expr>,
        else_branch: Box<Expr>,
        span: Span,
    },
    With {
        env: Box<Expr>,
        body: Box<Expr>,
        span: Span,
    },
    Assert {
        cond: Box<Expr>,
        body: Box<Expr>,
        span: Span,
    },
    LetIn {
        bindings: Vec<Binding>,
        body: Box<Expr>,
        span: Span,
    },
    LambdaPositional {
        arg: Ident,
        body: Box<Expr>,
        span: Span,
    },
    LambdaPattern {
        pattern: PatternSpec,
        at_pattern: Option<Ident>,
        body: Box<Expr>,
        span: Span,
    },
}

#[derive(Debug, Clone)]
pub enum StringPart {
    Literal(String),
    Interpol(Expr),
}

#[derive(Debug, Clone)]
pub enum Binding {
    Val {
        attr_path: Vec<Ident>,
        val: Expr,
        full_span: Span,
    },
    Inherit {
        from: Option<Expr>,
        attrs: Vec<Ident>,
        full_span: Span,
    },
}

#[derive(Debug, Clone)]
pub struct PatternSpec {
    pub args: Vec<PatternArg>,
    pub ellipsis: bool,
    pub span: Span,
}

#[derive(Debug, Clone)]
pub struct PatternArg {
    pub name: Ident,
    pub default: Option<Expr>,
    pub span: Span,
    pub full_span: Span, // includes default and comma if needed
}
EOF"}

