    }

    fn byte_pos(&self) -> usize {
        if self.pos < self.chars.len() {
            self.chars[self.pos].0
        } else {
            self.src.len()
        }
    }

    fn line_col(&self, byte_idx: usize) -> (usize, usize) {
        let mut line = 1;
        let mut col = 1;
        for (i, c) in self.src.char_indices() {
            if i >= byte_idx {
                break;
            }
            if c == '\n' {
                line += 1;
                col = 1;
            } else {
                col += 1;
            }
        }
        (line, col)
    }

    pub fn make_span(&self, start_byte: usize, end_byte: usize) -> Span {
        let (start_line, start_col) = self.line_col(start_byte);
        let (end_line, end_col) = self.line_col(end_byte);
        Span {
            start: start_byte,
            end: end_byte,
            start_line,
            start_col,
            end_line,
            end_col,
        }
    }

    pub fn tokenize_all(&mut self) -> Vec<Token> {
        let mut tokens = Vec::new();
        loop {
            let tok = self.next_token();
            let is_eof = tok.kind == TokenKind::Eof;
            tokens.push(tok);
            if is_eof {
                break;
            }
        }
        tokens
    }

    pub fn next_token(&mut self) -> Token {
        self.skip_whitespace();

        let start_byte = self.byte_pos();
        if self.pos >= self.chars.len() {
            return Token {
                kind: TokenKind::Eof,
                span: self.make_span(start_byte, start_byte),
            };
        }

        let c = self.peek().unwrap();

        // Line comment
        if c == '#' {
            let comment = self.read_line_comment();
            let end_byte = self.byte_pos();
            let span = self.make_span(start_byte, end_byte);
            if comment.contains("deadnix: skip") || comment.contains("deadnix:skip") {
                self.skip_comment_lines.push(span.start_line);
            }
            return Token {
                kind: TokenKind::Comment(comment),
                span,
            };
        }

        // Block comment
        if c == '/' && self.peek_next() == Some('*') {
            let comment = self.read_block_comment();
            let end_byte = self.byte_pos();
            let span = self.make_span(start_byte, end_byte);
            if comment.contains("deadnix: skip") || comment.contains("deadnix:skip") {
                self.skip_comment_lines.push(span.start_line);
            }
            return Token {
                kind: TokenKind::Comment(comment),
                span,
            };
        }

        // Identifiers or Keywords
        if c.is_ascii_alphabetic() || c == '_' {
            let s = self.read_ident();
            let end_byte = self.byte_pos();
            let kind = match s.as_str() {
                "let" => TokenKind::Let,
                "in" => TokenKind::In,
                "rec" => TokenKind::Rec,
                "with" => TokenKind::With,
                "if" => TokenKind::If,
                "then" => TokenKind::Then,
                "else" => TokenKind::Else,
                "assert" => TokenKind::Assert,
                "inherit" => TokenKind::Inherit,
                "or" => TokenKind::Or,
                _ => TokenKind::Ident(s),
            };
            return Token {
                kind,
                span: self.make_span(start_byte, end_byte),
            };
        }

        // Numbers
        if c.is_ascii_digit() {
            let (num_str, is_float) = self.read_number();
            let end_byte = self.byte_pos();
            let kind = if is_float {
                TokenKind::Float(num_str.parse().unwrap_or(0.0))
            } else {
                TokenKind::Int(num_str.parse().unwrap_or(0))
            };
            return Token {
                kind,
                span: self.make_span(start_byte, end_byte),
            };
        }

        // Strings
        if c == '"' {
            self.advance();
            let end_byte = self.byte_pos();
            return Token {
                kind: TokenKind::StringLit("\"".to_string()),
                span: self.make_span(start_byte, end_byte),
            };
        }

        if c == '\'' && self.peek_next() == Some('\'') {
            self.advance();
            self.advance();
            let end_byte = self.byte_pos();
            return Token {
                kind: TokenKind::IndentedStringStart,
                span: self.make_span(start_byte, end_byte),
            };
        }

        // Paths: ./path or /path or ~/path or <path>
        if (c == '.' || c == '/' || c == '~') && (self.peek_next() == Some('/') || self.peek_next() == Some('.')) {
            let path = self.read_path();
            let end_byte = self.byte_pos();
            return Token {
                kind: TokenKind::Path(path),
                span: self.make_span(start_byte, end_byte),
            };
        }

        if c == '<' {
            if let Some(path) = self.try_read_angle_path() {
                let end_byte = self.byte_pos();
                return Token {
                    kind: TokenKind::Path(path),
                    span: self.make_span(start_byte, end_byte),
                };
            }
        }

        // Multi-char operators
        if c == '.' && self.peek_next() == Some('.') && self.peek_third() == Some('.') {
            self.advance(); self.advance(); self.advance();
            let end_byte = self.byte_pos();
            return Token { kind: TokenKind::Ellipsis, span: self.make_span(start_byte, end_byte) };
        }
        if c == '$' && self.peek_next() == Some('{') {
            self.advance(); self.advance();
            let end_byte = self.byte_pos();
            return Token { kind: TokenKind::InterpolStart, span: self.make_span(start_byte, end_byte) };
        }
        if c == '=' && self.peek_next() == Some('=') {
            self.advance(); self.advance();
            let end_byte = self.byte_pos();
            return Token { kind: TokenKind::Eq, span: self.make_span(start_byte, end_byte) };
        }
        if c == '!' && self.peek_next() == Some('=') {
            self.advance(); self.advance();
            let end_byte = self.byte_pos();
            return Token { kind: TokenKind::Neq, span: self.make_span(start_byte, end_byte) };
        }
        if c == '<' && self.peek_next() == Some('=') {
            self.advance(); self.advance();
            let end_byte = self.byte_pos();
            return Token { kind: TokenKind::Le, span: self.make_span(start_byte, end_byte) };
        }
        if c == '>' && self.peek_next() == Some('=') {
            self.advance(); self.advance();
            let end_byte = self.byte_pos();
            return Token { kind: TokenKind::Ge, span: self.make_span(start_byte, end_byte) };
        }
        if c == '&' && self.peek_next() == Some('&') {
            self.advance(); self.advance();
            let end_byte = self.byte_pos();
            return Token { kind: TokenKind::And, span: self.make_span(start_byte, end_byte) };
        }
        if c == '|' && self.peek_next() == Some('|') {
            self.advance(); self.advance();
            let end_byte = self.byte_pos();
            return Token { kind: TokenKind::OrOp, span: self.make_span(start_byte, end_byte) };
        }
        if c == '-' && self.peek_next() == Some('>') {
            self.advance(); self.advance();
            let end_byte = self.byte_pos();
            return Token { kind: TokenKind::Impl, span: self.make_span(start_byte, end_byte) };
        }
        if c == '/' && self.peek_next() == Some('/') {
            self.advance(); self.advance();
            let end_byte = self.byte_pos();
            return Token { kind: TokenKind::Update, span: self.make_span(start_byte, end_byte) };
        }
        if c == '+' && self.peek_next() == Some('+') {
            self.advance(); self.advance();
            let end_byte = self.byte_pos();
            return Token { kind: TokenKind::Concat, span: self.make_span(start_byte, end_byte) };
        }

        // Single-char symbols
        self.advance();
        let end_byte = self.byte_pos();
        let kind = match c {
            '{' => TokenKind::LBrace,
            '}' => TokenKind::RBrace,
            '(' => TokenKind::LParen,
            ')' => TokenKind::RParen,
            '[' => TokenKind::LBracket,
            ']' => TokenKind::RBracket,
            ':' => TokenKind::Colon,
            ';' => TokenKind::Semicolon,
            ',' => TokenKind::Comma,
            '.' => TokenKind::Dot,
            '=' => TokenKind::Assign,
            '@' => TokenKind::At,
            '?' => TokenKind::Question,
            '+' => TokenKind::Plus,
            '-' => TokenKind::Minus,
            '*' => TokenKind::Mul,
            '/' => TokenKind::Div,
            '<' => TokenKind::Lt,
            '>' => TokenKind::Gt,
            '!' => TokenKind::Not,
            _ => TokenKind::Ident(c.to_string()),
        };

        Token {
            kind,
            span: self.make_span(start_byte, end_byte),
        }
    }

    fn peek_third(&self) -> Option<char> {
        if self.pos + 2 < self.chars.len() {
            Some(self.chars[self.pos + 2].1)
        } else {
            None
        }
    }

    fn skip_whitespace(&mut self) {
        while let Some(c) = self.peek() {
            if c.is_whitespace() {
                self.advance();
            } else {
                break;
            }
        }
    }

    fn read_line_comment(&mut self) -> String {
        let mut s = String::new();
        while let Some(c) = self.peek() {
            if c == '\n' {
                break;
            }
            s.push(c);
            self.advance();
        }
        s
    }

    fn read_block_comment(&mut self) -> String {
        let mut s = String::new();
        self.advance(); // '/'
        self.advance(); // '*'
        s.push_str("/*");
        while let Some(c) = self.peek() {
            if c == '*' && self.peek_next() == Some('/') {
                s.push_str("*/");
                self.advance();
                self.advance();
                break;
            }
            s.push(c);
            self.advance();
        }
        s
    }

    fn read_ident(&mut self) -> String {
        let mut s = String::new();
        while let Some(c) = self.peek() {
            if c.is_ascii_alphanumeric() || c == '_' || c == '\'' || c == '-' {
                s.push(c);
                self.advance();
            } else {
                break;
            }
        }
        s
    }

    fn read_number(&mut self) -> (String, bool) {
        let mut s = String::new();
        let mut is_float = false;
        while let Some(c) = self.peek() {
            if c.is_ascii_digit() {
                s.push(c);
                self.advance();
            } else if c == '.' && !is_float && self.peek_next().map_or(false, |next| next.is_ascii_digit()) {
                is_float = true;
                s.push(c);
                self.advance();
            } else {
                break;
            }
        }
        (s, is_float)
    }

    fn read_path(&mut self) -> String {
        let mut s = String::new();
        while let Some(c) = self.peek() {
            if c.is_ascii_alphanumeric() || c == '_' || c == '.' || c == '/' || c == '-' || c == '~' {
                s.push(c);
                self.advance();
            } else {
                break;
            }
        }
        s
    }

    fn try_read_angle_path(&mut self) -> Option<String> {
        let save_pos = self.pos;
        self.advance(); // '<'
        let mut s = String::from("<");
        let mut found_end = false;
        while let Some(c) = self.peek() {
            if c == '>' {
                s.push('>');
                self.advance();
                found_end = true;
                break;
            } else if c.is_ascii_alphanumeric() || c == '_' || c == '.' || c == '/' || c == '-' {
                s.push(c);
                self.advance();
            } else {
                break;
            }
        }
        if found_end {
            Some(s)
        } else {
            self.pos = save_pos;
            None
        }
    }
}
