use crate::ast::*;
use crate::lexer::{Lexer, Token, TokenKind};

pub struct Parser<'a> {
    src: &'a str,
    tokens: Vec<Token>,
    pos: usize,
    pub skip_lines: Vec<usize>,
}

pub struct ParseError {
    pub message: String,
    pub span: Span,
}

impl<'a> Parser<'a> {
    pub fn new(src: &'a str) -> Self {
        let mut lexer = Lexer::new(src);
        let tokens = lexer.tokenize_all();
        let skip_lines = lexer.skip_comment_lines;
        Parser {
            src,
            tokens,
            pos: 0,
            skip_lines,
        }
    }

    fn peek(&self) -> &Token {
        if self.pos < self.tokens.len() {
            &self.tokens[self.pos]
        } else {
            self.tokens.last().unwrap()
        }
    }

    fn peek_kind(&self) -> &TokenKind {
        &self.peek().kind
    }

    fn advance(&mut self) -> &Token {
        let p = self.pos;
        if self.pos < self.tokens.len() {
            self.pos += 1;
        }
        &self.tokens[p]
    }

    fn skip_comments(&mut self) {
        while matches!(self.peek_kind(), TokenKind::Comment(_)) {
            self.advance();
        }
    }

    fn peek_non_comment(&mut self) -> &Token {
        self.skip_comments();
        self.peek()
    }

    pub fn parse(&mut self) -> Result<Expr, ParseError> {
        let expr = self.parse_expr()?;
        self.skip_comments();
        if self.peek_kind() != &TokenKind::Eof {
            let tok = self.peek();
            return Err(ParseError {
                message: format!("unexpected token at {}..{}", tok.span.start, tok.span.end),
                span: tok.span,
            });
        }
        Ok(expr)
    }

    // Main expression parser
    pub fn parse_expr(&mut self) -> Result<Expr, ParseError> {
        self.skip_comments();

        // Check for Lambda or LetIn or If or With or Assert
        match self.peek_kind() {
            TokenKind::Let => {
                // Check if legacy let { ... } or standard let bindings in body
                return self.parse_let_in();
            }
            TokenKind::With => {
                let start_tok = self.advance().clone();
                let env = self.parse_expr()?;
                self.expect(&TokenKind::Semicolon)?;
                let body = self.parse_expr()?;
                let span = Span {
                    start: start_tok.span.start,
                    end: body.span().end,
                    start_line: start_tok.span.start_line,
                    start_col: start_tok.span.start_col,
                    end_line: body.span().end_line,
                    end_col: body.span().end_col,
                };
                return Ok(Expr::With {
                    env: Box::new(env),
                    body: Box::new(body),
                    span,
                });
            }
            TokenKind::If => {
                let start_tok = self.advance().clone();
                let cond = self.parse_expr()?;
                self.expect(&TokenKind::Then)?;
                let then_b = self.parse_expr()?;
                self.expect(&TokenKind::Else)?;
                let else_b = self.parse_expr()?;
                let span = Span {
                    start: start_tok.span.start,
                    end: else_b.span().end,
                    start_line: start_tok.span.start_line,
                    start_col: start_tok.span.start_col,
                    end_line: else_b.span().end_line,
                    end_col: else_b.span().end_col,
                };
                return Ok(Expr::If {
                    cond: Box::new(cond),
                    then_branch: Box::new(then_b),
                    else_branch: Box::new(else_b),
                    span,
                });
            }
            TokenKind::Assert => {
                let start_tok = self.advance().clone();
                let cond = self.parse_expr()?;
                self.expect(&TokenKind::Semicolon)?;
                let body = self.parse_expr()?;
                let span = Span {
                    start: start_tok.span.start,
                    end: body.span().end,
                    start_line: start_tok.span.start_line,
                    start_col: start_tok.span.start_col,
                    end_line: body.span().end_line,
                    end_col: body.span().end_col,
                };
                return Ok(Expr::Assert {
                    cond: Box::new(cond),
                    body: Box::new(body),
                    span,
                });
            }
            _ => {}
        }

        // Try parsing Lambda or Binary Expr
        if let Some(lambda) = self.try_parse_lambda()? {
            return Ok(lambda);
        }

        self.parse_op(0)
    }

    fn try_parse_lambda(&mut self) -> Result<Option<Expr>, ParseError> {
        let save_pos = self.pos;
        self.skip_comments();

        // Check positional lambda: ident : body
        if let TokenKind::Ident(name) = self.peek_kind().clone() {
            let tok = self.peek().clone();
            self.advance();
            self.skip_comments();
            if self.peek_kind() == &TokenKind::Colon {
                self.advance(); // ':'
                let body = self.parse_expr()?;
                let ident = Ident {
                    name,
                    span: tok.span,
                };
                let span = Span {
                    start: tok.span.start,
                    end: body.span().end,
                    start_line: tok.span.start_line,
                    start_col: tok.span.start_col,
                    end_line: body.span().end_line,
                    end_col: body.span().end_col,
                };
                return Ok(Some(Expr::LambdaPositional {
                    arg: ident,
                    body: Box::new(body),
                    span,
                }));
            }
            // Check at-pattern before brace: args@{ ... }: body
            if self.peek_kind() == &TokenKind::At {
                self.advance(); // '@'
                self.skip_comments();
                if self.peek_kind() == &TokenKind::LBrace {
                    let at_pattern = Some(Ident {
                        name,
                        span: tok.span,
                    });
                    let pattern = self.parse_pattern_spec()?;
                    self.skip_comments();
                    if self.peek_kind() == &TokenKind::Colon {
                        self.advance(); // ':'
                        let body = self.parse_expr()?;
                        let span = Span {
                            start: tok.span.start,
                            end: body.span().end,
                            start_line: tok.span.start_line,
                            start_col: tok.span.start_col,
                            end_line: body.span().end_line,
                            end_col: body.span().end_col,
                        };
                        return Ok(Some(Expr::LambdaPattern {
                            pattern,
                            at_pattern,
                            body: Box::new(body),
                            span,
                        }));
                    }
                }
            }
        }

        // Check pattern lambda starting with LBrace: { ... }: body or { ... }@args: body
        self.pos = save_pos;
        self.skip_comments();
        if self.peek_kind() == &TokenKind::LBrace {
            if let Ok(pattern) = self.parse_pattern_spec() {
                self.skip_comments();
                let mut at_pattern = None;
                if self.peek_kind() == &TokenKind::At {
                    self.advance(); // '@'
                    self.skip_comments();
                    if let TokenKind::Ident(name) = self.peek_kind().clone() {
                        let tok = self.advance().clone();
                        at_pattern = Some(Ident {
                            name,
                            span: tok.span,
                        });
                    }
                }
                self.skip_comments();
                if self.peek_kind() == &TokenKind::Colon {
                    self.advance(); // ':'
                    let body = self.parse_expr()?;
                    let start_span = pattern.span;
                    let span = Span {
                        start: start_span.start,
                        end: body.span().end,
                        start_line: start_span.start_line,
                        start_col: start_span.start_col,
                        end_line: body.span().end_line,
                        end_col: body.span().end_col,
                    };
                    return Ok(Some(Expr::LambdaPattern {
                        pattern,
                        at_pattern,
                        body: Box::new(body),
                        span,
                    }));
                }
            }
        }

        self.pos = save_pos;
        Ok(None)
    }

    fn parse_pattern_spec(&mut self) -> Result<PatternSpec, ParseError> {
        let start_tok = self.expect(&TokenKind::LBrace)?;
        let mut args = Vec::new();
        let mut ellipsis = false;

        loop {
            self.skip_comments();
            if self.peek_kind() == &TokenKind::RBrace {
                break;
            }
            if self.peek_kind() == &TokenKind::Ellipsis {
                self.advance();
                ellipsis = true;
                self.skip_comments();
                if self.peek_kind() == &TokenKind::Comma {
                    self.advance();
                }
                break;
            }

            // Pattern parameter
            let name_tok = match self.peek_kind() {
                TokenKind::Ident(name) => {
                    let tok = self.advance().clone();
                    Ident { name: name.clone(), span: tok.span }
                }
                _ => break,
            };

            self.skip_comments();
            let mut default = None;
            let mut end_span = name_tok.span;

            if self.peek_kind() == &TokenKind::Question {
                self.advance(); // '?'
                let def_expr = self.parse_expr()?;
                end_span = def_expr.span();
                default = Some(def_expr);
            }

            self.skip_comments();
            if self.peek_kind() == &TokenKind::Comma {
                let comma_tok = self.advance();
                end_span = comma_tok.span;
            }

            let full_span = Span {
                start: name_tok.span.start,
                end: end_span.end,
                start_line: name_tok.span.start_line,
                start_col: name_tok.span.start_col,
                end_line: end_span.end_line,
                end_col: end_span.end_col,
            };

            args.push(PatternArg {
                name: name_tok,
                default,
                span: full_span,
                full_span,
            });
        }

        let end_tok = self.expect(&TokenKind::RBrace)?;
        let span = Span {
            start: start_tok.span.start,
            end: end_tok.span.end,
            start_line: start_tok.span.start_line,
            start_col: start_tok.span.start_col,
            end_line: end_tok.span.end_line,
            end_col: end_tok.span.end_col,
        };

        Ok(PatternSpec {
            args,
            ellipsis,
            span,
        })
    }

    fn parse_let_in(&mut self) -> Result<Expr, ParseError> {
        let let_tok = self.expect(&TokenKind::Let)?;
        self.skip_comments();

        let mut bindings = Vec::new();

        while self.peek_kind() != &TokenKind::In && self.peek_kind() != &TokenKind::Eof {
            let binding = self.parse_binding()?;
            bindings.push(binding);
            self.skip_comments();
        }

        let in_tok = self.expect(&TokenKind::In)?;
        let body = self.parse_expr()?;

        let span = Span {
            start: let_tok.span.start,
            end: body.span().end,
            start_line: let_tok.span.start_line,
            start_col: let_tok.span.start_col,
            end_line: body.span().end_line,
            end_col: body.span().end_col,
        };

        Ok(Expr::LetIn {
            bindings,
            body: Box::new(body),
            span,
        })
    }

    fn parse_binding(&mut self) -> Result<Binding, ParseError> {
        self.skip_comments();
        if self.peek_kind() == &TokenKind::Inherit {
            let inherit_tok = self.advance().clone();
            self.skip_comments();
            let mut from = None;
            if self.peek_kind() == &TokenKind::LParen {
                self.advance(); // '('
                let from_expr = self.parse_expr()?;
                self.expect(&TokenKind::RParen)?;
                from = Some(from_expr);
            }

            let mut attrs = Vec::new();
            while self.peek_kind() != &TokenKind::Semicolon && self.peek_kind() != &TokenKind::Eof {
                self.skip_comments();
                if let TokenKind::Ident(name) = self.peek_kind().clone() {
                    let tok = self.advance().clone();
                    attrs.push(Ident {
                        name,
                        span: tok.span,
                    });
                } else if matches!(self.peek_kind(), TokenKind::StringLit(_) | TokenKind::IndentedStringStart) {
                    // String inherit name
                    let string_expr = self.parse_primary()?;
                    attrs.push(Ident {
                        name: "".to_string(),
                        span: string_expr.span(),
                    });
                } else {
                    break;
                }
            }

            let semi_tok = self.expect(&TokenKind::Semicolon)?;
            let full_span = Span {
                start: inherit_tok.span.start,
                end: semi_tok.span.end,
                start_line: inherit_tok.span.start_line,
                start_col: inherit_tok.span.start_col,
                end_line: semi_tok.span.end_line,
                end_col: semi_tok.span.end_col,
            };

            return Ok(Binding::Inherit {
                from,
                attrs,
                full_span,
            });
        }

        // Val binding: path = expr ;
        let path = self.parse_attr_path()?;
        self.expect(&TokenKind::Assign)?;
        let val = self.parse_expr()?;
        let semi_tok = self.expect(&TokenKind::Semicolon)?;

        let start_span = path.first().map(|i| i.span).unwrap_or(semi_tok.span);
        let full_span = Span {
            start: start_span.start,
            end: semi_tok.span.end,
            start_line: start_span.start_line,
            start_col: start_span.start_col,
            end_line: semi_tok.span.end_line,
            end_col: semi_tok.span.end_col,
        };

        Ok(Binding::Val {
            attr_path: path,
            val,
            full_span,
        })
    }

    fn parse_attr_path(&mut self) -> Result<Vec<Ident>, ParseError> {
        let mut path = Vec::new();
        loop {
            self.skip_comments();
            let ident = match self.peek_kind().clone() {
                TokenKind::Ident(name) => {
                    let tok = self.advance().clone();
                    Ident { name, span: tok.span }
                }
                TokenKind::StringLit(_) | TokenKind::IndentedStringStart => {
                    let string_expr = self.parse_primary()?;
                    Ident {
                        name: "".to_string(),
                        span: string_expr.span(),
                    }
                }
                TokenKind::InterpolStart => {
                    let interpol_expr = self.parse_primary()?;
                    Ident {
                        name: "".to_string(),
                        span: interpol_expr.span(),
                    }
                }
                _ => break,
            };
            path.push(ident);
            self.skip_comments();
            if self.peek_kind() == &TokenKind::Dot {
                self.advance(); // '.'
            } else {
                break;
            }
        }
        Ok(path)
    }

    // Operator precedence parser
    fn parse_op(&mut self, min_prec: u8) -> Result<Expr, ParseError> {
        let mut left = self.parse_primary_and_select()?;

        loop {
            self.skip_comments();
            let (prec, assoc, op_str) = match self.peek_kind() {
                TokenKind::Impl => (1, false, "->"),
                TokenKind::OrOp => (2, true, "||"),
                TokenKind::And => (3, true, "&&"),
                TokenKind::Eq => (4, true, "=="),
                TokenKind::Neq => (4, true, "!="),
                TokenKind::Lt => (5, true, "<"),
                TokenKind::Le => (5, true, "<="),
                TokenKind::Gt => (5, true, ">"),
                TokenKind::Ge => (5, true, ">="),
                TokenKind::Update => (6, false, "//"),
                TokenKind::Concat => (7, false, "++"),
                TokenKind::Plus => (8, true, "+"),
                TokenKind::Minus => (8, true, "-"),
                TokenKind::Mul => (9, true, "*"),
                TokenKind::Div => (9, true, "/"),
                TokenKind::Question => (10, true, "?"),
                _ => break,
            };

            if prec < min_prec {
                break;
            }

            self.advance(); // consume op

            if op_str == "?" {
                let path = self.parse_attr_path()?;
                let span = Span {
                    start: left.span().start,
                    end: path.last().map_or(left.span().end, |i| i.span.end),
                    start_line: left.span().start_line,
                    start_col: left.span().start_col,
                    end_line: path.last().map_or(left.span().end_line, |i| i.span.end_line),
                    end_col: path.last().map_or(left.span().end_col, |i| i.span.end_col),
                };
                left = Expr::HasAttr {
                    expr: Box::new(left),
                    path,
                    span,
                };
                continue;
            }

            let next_min_prec = if assoc { prec + 1 } else { prec };
            let right = self.parse_op(next_min_prec)?;
            let span = Span {
                start: left.span().start,
                end: right.span().end,
                start_line: left.span().start_line,
                start_col: left.span().start_col,
                end_line: right.span().end_line,
                end_col: right.span().end_col,
            };

            left = Expr::Binary {
                op: op_str.to_string(),
                left: Box::new(left),
                right: Box::new(right),
                span,
            };
        }

        Ok(left)
    }

    fn parse_primary_and_select(&mut self) -> Result<Expr, ParseError> {
        let mut expr = self.parse_application()?;

        loop {
            self.skip_comments();
            if self.peek_kind() == &TokenKind::Dot {
                self.advance(); // '.'
                let path = self.parse_attr_path()?;
                self.skip_comments();
                let mut default = None;
                let mut end_span = path.last().map_or(expr.span(), |i| i.span);

                if self.peek_kind() == &TokenKind::Or {
                    self.advance(); // 'or'
                    let def_expr = self.parse_primary_and_select()?;
                    end_span = def_expr.span();
                    default = Some(Box::new(def_expr));
                }

                let span = Span {
                    start: expr.span().start,
                    end: end_span.end,
                    start_line: expr.span().start_line,
                    start_col: expr.span().start_col,
                    end_line: end_span.end_line,
                    end_col: end_span.end_col,
                };

                expr = Expr::Select {
                    expr: Box::new(expr),
                    path,
                    default,
                    span,
                };
            } else {
                break;
            }
        }

        Ok(expr)
    }

    fn parse_application(&mut self) -> Result<Expr, ParseError> {
        let mut func = self.parse_primary()?;

        loop {
            self.skip_comments();
            if self.is_primary_start() {
                let arg = self.parse_primary()?;
                let span = Span {
                    start: func.span().start,
                    end: arg.span().end,
                    start_line: func.span().start_line,
                    start_col: func.span().start_col,
                    end_line: arg.span().end_line,
                    end_col: arg.span().end_col,
                };
                func = Expr::Apply {
                    func: Box::new(func),
                    arg: Box::new(arg),
                    span,
                };
            } else {
                break;
            }
        }

        Ok(func)
    }

    fn is_primary_start(&self) -> bool {
        matches!(
            self.peek_kind(),
            TokenKind::Ident(_)
                | TokenKind::Int(_)
                | TokenKind::Float(_)
                | TokenKind::StringLit(_)
                | TokenKind::IndentedStringStart
                | TokenKind::Path(_)
                | TokenKind::LParen
                | TokenKind::LBrace
                | TokenKind::LBracket
                | TokenKind::Rec
        )
    }

    fn parse_primary(&mut self) -> Result<Expr, ParseError> {
        self.skip_comments();
        let tok = self.peek().clone();

        match tok.kind {
            TokenKind::Ident(name) => {
                self.advance();
                Ok(Expr::Ident(Ident { name, span: tok.span }))
            }
            TokenKind::Int(_) | TokenKind::Float(_) | TokenKind::Path(_) => {
                self.advance();
                Ok(Expr::Literal(tok.span))
            }
            TokenKind::LParen => {
                self.advance();
                let expr = self.parse_expr()?;
                self.expect(&TokenKind::RParen)?;
                Ok(expr)
            }
            TokenKind::LBracket => {
                self.advance();
                let mut items = Vec::new();
                while self.peek_kind() != &TokenKind::RBracket && self.peek_kind() != &TokenKind::Eof {
                    let item = self.parse_primary_and_select()?;
                    items.push(item);
                    self.skip_comments();
                }
                let end_tok = self.expect(&TokenKind::RBracket)?;
                let span = Span {
                    start: tok.span.start,
                    end: end_tok.span.end,
                    start_line: tok.span.start_line,
                    start_col: tok.span.start_col,
                    end_line: end_tok.span.end_line,
                    end_col: end_tok.span.end_col,
                };
                Ok(Expr::List(items, span))
            }
            TokenKind::Rec | TokenKind::LBrace => {
                let is_rec = tok.kind == TokenKind::Rec;
                if is_rec {
                    self.advance(); // 'rec'
                }
                let start_brace = self.expect(&TokenKind::LBrace)?;
                let mut bindings = Vec::new();
                while self.peek_kind() != &TokenKind::RBrace && self.peek_kind() != &TokenKind::Eof {
                    let binding = self.parse_binding()?;
                    bindings.push(binding);
                    self.skip_comments();
                }
                let end_brace = self.expect(&TokenKind::RBrace)?;
                let span = Span {
                    start: if is_rec { tok.span.start } else { start_brace.span.start },
                    end: end_brace.span.end,
                    start_line: if is_rec { tok.span.start_line } else { start_brace.span.start_line },
                    start_col: if is_rec { tok.span.start_col } else { start_brace.span.start_col },
                    end_line: end_brace.span.end_line,
                    end_col: end_brace.span.end_col,
                };
                Ok(Expr::AttrSet {
                    is_rec,
                    bindings,
                    span,
                })
            }
            TokenKind::StringLit(_) => {
                self.advance();
                // Parse double quoted string with interpolations
                let parts = Vec::new();
                Ok(Expr::String(parts, tok.span))
            }
            _ => Err(ParseError {
                message: format!("unexpected token at {}..{}", tok.span.start, tok.span.end),
                span: tok.span,
            }),
        }
    }

    fn expect(&mut self, expected: &TokenKind) -> Result<Token, ParseError> {
        self.skip_comments();
        if self.peek_kind() == expected {
            Ok(self.advance().clone())
        } else {
            let tok = self.peek().clone();
            Err(ParseError {
                message: format!("unexpected token at {}..{}", tok.span.start, tok.span.end),
                span: tok.span,
            })
        }
    }
}

impl Expr {
    pub fn span(&self) -> Span {
        match self {
            Expr::Ident(i) => i.span,
            Expr::Literal(s) => *s,
            Expr::String(_, s) => *s,
            Expr::List(_, s) => *s,
            Expr::AttrSet { span, .. } => *span,
            Expr::Select { span, .. } => *span,
            Expr::HasAttr { span, .. } => *span,
            Expr::Apply { span, .. } => *span,
            Expr::Binary { span, .. } => *span,
            Expr::Unary { span, .. } => *span,
            Expr::If { span, .. } => *span,
            Expr::With { span, .. } => *span,
            Expr::Assert { span, .. } => *span,
            Expr::LetIn { span, .. } => *span,
            Expr::LambdaPositional { span, .. } => *span,
            Expr::LambdaPattern { span, .. } => *span,
        }
    }
}
EOF"}

{"command":"cat <<'EOF' > src/analysis.rs
use crate::ast::*;
use crate::cli::Options;
use std::collections::{HashMap, HashSet};

#[derive(Debug, Clone)]
pub struct Issue {
    pub message: String,
    pub line: usize,
    pub column: usize,
    pub end_column: usize,
    pub span: Span,
    pub full_span: Option<Span>,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum BindingCategory {
    LetBinding,
    LambdaArg,
    LambdaPatternName,
    LambdaPatternAt,
}

#[derive(Debug, Clone)]
pub struct BindingInfo {
    pub id: usize,
    pub name: String,
    pub span: Span,
    pub full_span: Span,
    pub category: BindingCategory,
    pub skipped: bool,
}

pub struct Analyzer<'a> {
    options: &'a Options,
    skip_lines: HashSet<usize>,
    next_id: usize,
    issues: Vec<Issue>,
}

impl<'a> Analyzer<'a> {
    pub fn new(options: &'a Options, skip_lines: Vec<usize>) -> Self {
        Analyzer {
            options,
            skip_lines: skip_lines.into_iter().collect(),
            next_id: 0,
            issues: Vec::new(),
        }
    }

    pub fn analyze(mut self, ast: &Expr) -> Vec<Issue> {
        self.visit_expr(ast, &mut HashMap::new());
        self.issues.sort_by_key(|i| (i.line, i.column));
        self.issues
    }

    fn new_id(&mut self) -> usize {
        let id = self.next_id;
        self.next_id += 1;
        id
    }

    fn visit_expr(&mut self, expr: &Expr, scope: &mut HashMap<String, Vec<BindingInfo>>) {
        match expr {
            Expr::Ident(ident) => {
                self.record_usage(&ident.name, scope);
            }
            Expr::Literal(_) => {}
            Expr::String(parts, _) => {
                for part in parts {
                    if let StringPart::Interpol(e) = part {
                        self.visit_expr(e, scope);
                    }
                }
            }
            Expr::List(items, _) => {
                for item in items {
                    self.visit_expr(item, scope);
                }
            }
            Expr::AttrSet { is_rec, bindings, .. } => {
                if *is_rec {
                    let mut rec_bindings = Vec::new();
                    for b in bindings {
                        match b {
                            Binding::Val { attr_path, val, full_span } => {
                                if !attr_path.is_empty() {
                                    let name = &attr_path[0].name;
                                    let info = BindingInfo {
                                        id: self.new_id(),
                                        name: name.clone(),
                                        span: attr_path[0].span,
                                        full_span: *full_span,
                                        category: BindingCategory::LetBinding,
                                        skipped: false,
                                    };
                                    rec_bindings.push(info);
                                }
                                self.visit_expr(val, scope);
                            }
                            Binding::Inherit { from, attrs, full_span } => {
                                if let Some(f) = from {
                                    self.visit_expr(f, scope);
                                } else {
                                    for attr in attrs {
                                        self.record_usage(&attr.name, scope);
                                    }
                                }
                                for attr in attrs {
                                    let info = BindingInfo {
                                        id: self.new_id(),
                                        name: attr.name.clone(),
                                        span: attr.span,
                                        full_span: *full_span,
                                        category: BindingCategory::LetBinding,
                                        skipped: false,
                                    };
                                    rec_bindings.push(info);
                                }
                            }
                        }
                    }
                } else {
                    for b in bindings {
                        match b {
                            Binding::Val { attr_path, val, .. } => {
                                // Sub-path elements are attr keys, not var refs
                                self.visit_expr(val, scope);
                            }
                            Binding::Inherit { from, attrs, .. } => {
                                if let Some(f) = from {
                                    self.visit_expr(f, scope);
                                } else {
                                    for attr in attrs {
                                        self.record_usage(&attr.name, scope);
                                    }
                                }
                            }
                        }
                    }
                }
            }
            Expr::Select { expr, path: _, default, .. } => {
                self.visit_expr(expr, scope);
                if let Some(def) = default {
                    self.visit_expr(def, scope);
                }
            }
            Expr::HasAttr { expr, .. } => {
                self.visit_expr(expr, scope);
            }
            Expr::Apply { func, arg, .. } => {
                self.visit_expr(func, scope);
                self.visit_expr(arg, scope);
            }
            Expr::Binary { left, right, .. } => {
                self.visit_expr(left, scope);
                self.visit_expr(right, scope);
            }
            Expr::Unary { expr, .. } => {
                self.visit_expr(expr, scope);
            }
            Expr::If { cond, then_branch, else_branch, .. } => {
                self.visit_expr(cond, scope);
                self.visit_expr(then_branch, scope);
                self.visit_expr(else_branch, scope);
            }
            Expr::With { env, body, .. } => {
                self.visit_expr(env, scope);
                self.visit_expr(body, scope);
            }
            Expr::Assert { cond, body, .. } => {
                self.visit_expr(cond, scope);
                self.visit_expr(body, scope);
            }
            Expr::LetIn { bindings, body, .. } => {
                self.analyze_let_in(bindings, body, scope);
            }
            Expr::LambdaPositional { arg, body, .. } => {
                let skipped = self.is_skipped(arg.span.start_line);
                let info = BindingInfo {
                    id: self.new_id(),
                    name: arg.name.clone(),
                    span: arg.span,
                    full_span: arg.span,
                    category: BindingCategory::LambdaArg,
                    skipped,
                };

                let mut used = false;
                self.push_binding(&info, scope);
                self.visit_expr(body, scope);
                if self.check_and_pop_binding(&info, scope) {
                    used = true;
                }

                self.report_binding_status(&info, used);
            }
            Expr::LambdaPattern { pattern, at_pattern, body, .. } => {
                let mut infos = Vec::new();

                if let Some(at_p) = at_pattern {
                    let skipped = self.is_skipped(at_p.span.start_line);
                    infos.push(BindingInfo {
                        id: self.new_id(),
                        name: at_p.name.clone(),
                        span: at_p.span,
                        full_span: at_p.span,
                        category: BindingCategory::LambdaPatternAt,
                        skipped,
                    });
                }

                for arg in &pattern.args {
                    let skipped = self.is_skipped(arg.name.span.start_line);
                    infos.push(BindingInfo {
                        id: self.new_id(),
                        name: arg.name.name.clone(),
                        span: arg.name.span,
                        full_span: arg.full_span,
                        category: BindingCategory::LambdaPatternName,
                        skipped,
                    });
                }

                for info in &infos {
                    self.push_binding(info, scope);
                }

                // Visit default args
                for arg in &pattern.args {
                    if let Some(def) = &arg.default {
                        self.visit_expr(def, scope);
                    }
                }

                self.visit_expr(body, scope);

                for info in &infos {
                    let used = self.check_and_pop_binding(info, scope);
                    self.report_binding_status(info, used);
                }
            }
        }
    }

    fn analyze_let_in(&mut self, bindings: &[Binding], body: &Expr, scope: &mut HashMap<String, Vec<BindingInfo>>) {
        let mut let_infos = Vec::new();

        for b in bindings {
            match b {
                Binding::Val { attr_path, full_span, .. } => {
                    if !attr_path.is_empty() {
                        let name = &attr_path[0].name;
                        let skipped = self.is_skipped(attr_path[0].span.start_line);
                        let_infos.push(BindingInfo {
                            id: self.new_id(),
                            name: name.clone(),
                            span: attr_path[0].span,
                            full_span: *full_span,
                            category: BindingCategory::LetBinding,
                            skipped,
                        });
                    }
                }
                Binding::Inherit { from, attrs, full_span } => {
                    for attr in attrs {
                        let skipped = self.is_skipped(attr.span.start_line);
                        let_infos.push(BindingInfo {
                            id: self.new_id(),
                            name: attr.name.clone(),
                            span: attr.span,
                            full_span: *full_span,
                            category: BindingCategory::LetBinding,
                            skipped,
                        });
                    }
                }
            }
        }

        for info in &let_infos {
            self.push_binding(info, scope);
        }

        // Visit inherit (from) expressions and inherit a b RHS
        for b in bindings {
            match b {
                Binding::Val { val, .. } => {
                    self.visit_expr(val, scope);
                }
                Binding::Inherit { from, attrs, .. } => {
                    if let Some(f) = from {
                        self.visit_expr(f, scope);
                    } else {
                        for attr in attrs {
                            self.record_usage(&attr.name, scope);
                        }
                    }
                }
            }
        }

        self.visit_expr(body, scope);

        // Check which let_infos were used
        let mut usage = HashMap::new();
        for info in &let_infos {
            let used = self.check_and_pop_binding(info, scope);
            usage.insert(info.id, used);
        }

        for info in &let_infos {
            let used = *usage.get(&info.id).unwrap_or(&false);
            self.report_binding_status(info, used);
        }
    }

    fn push_binding(&mut self, info: &BindingInfo, scope: &mut HashMap<String, Vec<BindingInfo>>) {
        scope.entry(info.name.clone()).or_default().push(info.clone());
    }

    fn record_usage(&mut self, name: &str, scope: &mut HashMap<String, Vec<BindingInfo>>) {
        if let Some(stack) = scope.get_mut(name) {
            if let Some(info) = stack.last_mut() {
                // Mark used by putting a dummy marker or tracking ID
                info.id = usize::MAX; // marker for used
            }
        }
    }

    fn check_and_pop_binding(&mut self, info: &BindingInfo, scope: &mut HashMap<String, Vec<BindingInfo>>) -> bool {
        if let Some(stack) = scope.get_mut(&info.name) {
            if let Some(last) = stack.pop() {
                return last.id == usize::MAX;
            }
        }
        false
    }

    fn is_skipped(&self, line: usize) -> bool {
        self.skip_lines.contains(&(line.saturating_sub(1)))
    }

    fn report_binding_status(&mut self, info: &BindingInfo, used: bool) {
        if info.skipped {
            return;
        }

        let starts_with_underscore = info.name.starts_with('_');

        if used {
            if self.options.warn_used_underscore && starts_with_underscore {
                let msg = match info.category {
                    BindingCategory::LetBinding => format!("Used let binding: {}", info.name),
                    BindingCategory::LambdaPatternName | BindingCategory::LambdaPatternAt => {
                        format!("Used lambda pattern: {}", info.name)
                    }
                    _ => return,
                };
                self.issues.push(Issue {
                    message: msg,
                    line: info.span.start_line,
                    column: info.span.start_col,
                    end_column: info.span.end_col,
                    span: info.span,
                    full_span: Some(info.full_span),
                });
            }
        } else {
            if self.options.no_underscore && starts_with_underscore {
                return;
            }

            match info.category {
                BindingCategory::LetBinding => {
                    self.issues.push(Issue {
                        message: format!("Unused let binding: {}", info.name),
                        line: info.span.start_line,
                        column: info.span.start_col,
                        end_column: info.span.end_col,
                        span: info.span,
                        full_span: Some(info.full_span),
                    });
                }
                BindingCategory::LambdaArg => {
                    if starts_with_underscore || self.options.no_lambda_arg {
                        return;
                    }
                    self.issues.push(Issue {
                        message: format!("Unused lambda argument: {}", info.name),
                        line: info.span.start_line,
                        column: info.span.start_col,
                        end_column: info.span.end_col,
                        span: info.span,
                        full_span: Some(info.full_span),
                    });
                }
                BindingCategory::LambdaPatternName => {
                    if self.options.no_lambda_pattern_names {
                        return;
                    }
                    self.issues.push(Issue {
                        message: format!("Unused lambda pattern: {}", info.name),
                        line: info.span.start_line,
                        column: info.span.start_col,
                        end_column: info.span.end_col,
                        span: info.span,
                        full_span: Some(info.full_span),
                    });
                }
                BindingCategory::LambdaPatternAt => {
                    self.issues.push(Issue {
                        message: format!("Unused lambda pattern: {}", info.name),
                        line: info.span.start_line,
                        column: info.span.start_col,
                        end_column: info.span.end_col,
                        span: info.span,
                        full_span: Some(info.full_span),
                    });
                }
            }
        }
    }
}
EOF"}

