use crate::analysis::Issue;
use serde::Serialize;
use std::collections::BTreeMap;
use std::env;

#[derive(Serialize)]
pub struct JsonReport {
    pub file: String,
    pub results: Vec<JsonResult>,
}

#[derive(Serialize)]
pub struct JsonResult {
    #[serde(skip_serializing_if = "Option::is_none")]
    pub column: Option<usize>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub endColumn: Option<usize>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub line: Option<usize>,
    pub message: String,
}

pub fn print_json_reports(file_path: &str, issues: &[Issue], parse_error: Option<&str>) {
    if let Some(err_msg) = parse_error {
        let report = JsonReport {
            file: file_path.to_string(),
            results: vec![JsonResult {
                column: None,
                endColumn: None,
                line: None,
                message: err_msg.to_string(),
            }],
        };
        println!("{}", serde_json::to_string(&report).unwrap());
        return;
    }

    if issues.is_empty() {
        return;
    }

    let results = issues
        .iter()
        .map(|i| JsonResult {
            column: Some(i.column),
            endColumn: Some(i.end_column),
            line: Some(i.line),
            message: i.message.clone(),
        })
        .collect();

    let report = JsonReport {
        file: file_path.to_string(),
        results,
    };

    println!("{}", serde_json::to_string(&report).unwrap());
}

pub fn print_human_report(file_path: &str, src: &str, issues: &[Issue]) {
    if issues.is_empty() {
        return;
    }

    let use_color = env::var_os("NO_COLOR").is_none();

    let c_yellow = if use_color { "\x1b[33m" } else { "" };
    let c_reset = if use_color { "\x1b[0m" } else { "" };
    let c_frame = if use_color { "\x1b[38;5;246m" } else { "" };
    let c_dark_frame = if use_color { "\x1b[38;5;240m" } else { "" };
    let c_code = if use_color { "\x1b[38;5;249m" } else { "" };

    println!("{}Warning:{} Unused declarations were found.", c_yellow, c_reset);

    let first_line = issues[0].line;
    let first_col = issues[0].column;

    // Group issues by line
    let mut line_issues: BTreeMap<usize, Vec<&Issue>> = BTreeMap::new();
    for issue in issues {
        line_issues.entry(issue.line).or_default().push(issue);
    }

    let max_line = *line_issues.keys().max().unwrap_or(&1);
    let line_num_width = std::cmp::max(3, max_line.to_string().len());
    let margin_width = line_num_width + 1;

    let margin_spaces = " ".repeat(margin_width);
    println!("{}╭─[{}", format_args!("{}{}", margin_spaces, c_frame), format_args!("{}:{}:{}]{}", file_path, first_line, first_col, c_reset));

    let src_lines: Vec<&str> = src.lines().collect();

    for (&line_num, line_iss) in &line_issues {
        let raw_line = if line_num > 0 && line_num <= src_lines.len() {
            src_lines[line_num - 1]
        } else {
            ""
        };

        // Format code line
        let formatted_code = format_code_line(raw_line, line_iss, use_color, c_code, c_reset);
        println!(
            "{}{:>width$} │{}{}",
            c_frame,
            line_num,
            formatted_code,
            c_reset,
            width = line_num_width
        );

        // Format pointer rows under the code line
        format_pointer_rows(line_iss, margin_width, use_color, c_dark_frame, c_reset);
    }
}

fn get_category_color(msg: &str) -> &'static str {
    if msg.contains("let binding") {
        "\x1b[31m" // Red
    } else if msg.contains("lambda pattern") {
        "\x1b[35m" // Magenta
    } else if msg.contains("lambda argument") {
        "\x1b[36m" // Cyan
    } else {
        "\x1b[31m"
    }
}

fn format_code_line(raw_line: &str, line_iss: &[&Issue], use_color: bool, c_code: &str, c_reset: &str) -> String {
    if !use_color {
        return raw_line.to_string();
    }

    let mut result = String::new();
    let chars: Vec<char> = raw_line.chars().collect();
    let mut i = 0;

    while i < chars.len() {
        let col = i + 1; // 1-based col
        let mut color_for_col = c_code;

        for issue in line_iss {
            if col >= issue.column && col < issue.end_column {
                color_for_col = get_category_color(&issue.message);
                break;
            }
        }

        result.push_str(color_for_col);
        result.push(chars[i]);
        result.push_str(c_reset);
        i += 1;
    }

    result
}

fn format_pointer_rows(line_iss: &[&Issue], margin_width: usize, use_color: bool, c_dark_frame: &str, c_reset: &str) {
    let margin_spaces = " ".repeat(margin_width);
    let frame_str = format!("{}│{}", c_dark_frame, c_reset);

    // Calculate pointer_col for each issue
    let mut items: Vec<(usize, usize, &'static str, &str)> = Vec::new();
    for issue in line_iss {
        let pointer_col = issue.column + (issue.end_column - issue.column) / 2;
        let color = if use_color { get_category_color(&issue.message) } else { "" };
        items.push((pointer_col, issue.end_column, color, &issue.message));
    }

    // Sort items by column ascending
    items.sort_by_key(|item| item.0);

    let k = items.len();
    if k == 0 {
        return;
    }

    let rightmost_col = items[k - 1].0;
    let rightmost_end = items[k - 1].1;
    let dashes_k = rightmost_end - rightmost_col;
    let text_start_col = rightmost_col + 1 + dashes_k + 1;

    // Output pointer lines from rightmost (index k-1) down to index 0
    for idx in (0..k).rev() {
        let (ptr_col, end_col, color, msg) = items[idx];
        let dashes = if idx == k - 1 {
            end_col - ptr_col
        } else {
            text_start_col.saturating_sub(ptr_col + 1)
        };

        let mut line_buf = format!("{}{} ", margin_spaces, frame_str);
        let current_len = 1; // 1 space after │

        // Vertical bars for items to the left (0..idx)
        let mut curr_col = 1;
        for j in 0..idx {
            let left_col = items[j].0;
            let left_color = items[j].2;
            let spaces_before = left_col.saturating_sub(curr_col);
            line_buf.push_str(&" ".repeat(spaces_before));
            line_buf.push_str(&format!("{}│{}", left_color, c_reset));
            curr_col = left_col + 1;
        }

        // Pointer ╰─── for item idx
        let spaces_before = ptr_col.saturating_sub(curr_col);
        line_buf.push_str(&" ".repeat(spaces_before));
        line_buf.push_str(&format!("{}╰{}", color, c_reset));
        line_buf.push_str(&format!("{}{}{}", color, "─".repeat(dashes), c_reset));
        line_buf.push_str(&format!(" {}", msg));

        println!("{}", line_buf);
    }
}
EOF"}

