        let formatted_code = format_code_line(raw_line, line_iss, use_color, c_code, c_reset);
        println!(
            "{}{:>width$} │{}{}",
            c_frame,
            line_num,
            formatted_code,
            c_reset,
            width = line_num_width
        );

        // Format pointer rows under the code line
        format_pointer_rows(line_iss, margin_width, use_color, c_dark_frame, c_reset);
    }
}

fn get_category_color(msg: &str) -> &'static str {
    if msg.contains("let binding") {
        "\x1b[31m" // Red
    } else if msg.contains("lambda pattern") {
        "\x1b[35m" // Magenta
    } else if msg.contains("lambda argument") {
        "\x1b[36m" // Cyan
    } else {
        "\x1b[31m"
    }
}

fn format_code_line(raw_line: &str, line_iss: &[&Issue], use_color: bool, c_code: &str, c_reset: &str) -> String {
    if !use_color {
        return raw_line.to_string();
    }

    let mut result = String::new();
    let chars: Vec<char> = raw_line.chars().collect();
    let mut i = 0;

    while i < chars.len() {
        let col = i + 1; // 1-based col
        let mut color_for_col = c_code;

        for issue in line_iss {
            if col >= issue.column && col < issue.end_column {
                color_for_col = get_category_color(&issue.message);
                break;
            }
        }

        result.push_str(color_for_col);
        result.push(chars[i]);
        result.push_str(c_reset);
        i += 1;
    }

    result
}

fn format_pointer_rows(line_iss: &[&Issue], margin_width: usize, use_color: bool, c_dark_frame: &str, c_reset: &str) {
    let margin_spaces = " ".repeat(margin_width);
    let frame_str = format!("{}│{}", c_dark_frame, c_reset);

    // Calculate pointer_col for each issue
    let mut items: Vec<(usize, usize, &'static str, &str)> = Vec::new();
    for issue in line_iss {
        let pointer_col = issue.column + (issue.end_column - issue.column) / 2;
        let color = if use_color { get_category_color(&issue.message) } else { "" };
        items.push((pointer_col, issue.end_column, color, &issue.message));
    }

    // Sort items by column ascending
    items.sort_by_key(|item| item.0);

    let k = items.len();
    if k == 0 {
        return;
    }

    let rightmost_col = items[k - 1].0;
    let rightmost_end = items[k - 1].1;
    let dashes_k = rightmost_end - rightmost_col;
    let text_start_col = rightmost_col + 1 + dashes_k + 1;

    // Output pointer lines from rightmost (index k-1) down to index 0
    for idx in (0..k).rev() {
        let (ptr_col, end_col, color, msg) = items[idx];
        let dashes = if idx == k - 1 {
            end_col - ptr_col
        } else {
            text_start_col.saturating_sub(ptr_col + 1)
        };

        let mut line_buf = format!("{}{} ", margin_spaces, frame_str);
        let current_len = 1; // 1 space after │

        // Vertical bars for items to the left (0..idx)
        let mut curr_col = 1;
        for j in 0..idx {
            let left_col = items[j].0;
            let left_color = items[j].2;
            let spaces_before = left_col.saturating_sub(curr_col);
            line_buf.push_str(&" ".repeat(spaces_before));
            line_buf.push_str(&format!("{}│{}", left_color, c_reset));
            curr_col = left_col + 1;
        }

        // Pointer ╰─── for item idx
        let spaces_before = ptr_col.saturating_sub(curr_col);
        line_buf.push_str(&" ".repeat(spaces_before));
        line_buf.push_str(&format!("{}╰{}", color, c_reset));
        line_buf.push_str(&format!("{}{}{}", color, "─".repeat(dashes), c_reset));
        line_buf.push_str(&format!(" {}", msg));

        println!("{}", line_buf);
    }
}
EOF"}

