                self.advance();
                self.mode_stack.pop();
                let end_byte = self.byte_pos();
                return Token {
                    kind: TokenKind::IndentedEnd,
                    span: self.make_span(start_byte, end_byte),
                };
            }
        }

        let mut lit = String::new();
        while let Some(c) = self.peek() {
            if c == '$' && self.peek_next() == Some('{') {
                if !lit.is_empty() {
                    let end_byte = self.byte_pos();
                    return Token {
                        kind: TokenKind::StringLit(lit),
                        span: self.make_span(start_byte, end_byte),
                    };
                }
                self.advance(); // '$'
                self.advance(); // '{'
                self.brace_stack.push(0);
                let end_byte = self.byte_pos();
                return Token {
                    kind: TokenKind::InterpolStart,
                    span: self.make_span(start_byte, end_byte),
                };
            }

            if mode == StringMode::DoubleQuote && c == '"' {
                break;
            }

            if mode == StringMode::Indented && c == '\'' && self.peek_next() == Some('\'') {
                break;
            }

            if c == '\\' {
                self.advance();
                if let Some(next_c) = self.peek() {
                    lit.push(next_c);
                    self.advance();
                }
                continue;
            }

            lit.push(c);
            self.advance();
        }

        let end_byte = self.byte_pos();
        Token {
            kind: TokenKind::StringLit(lit),
            span: self.make_span(start_byte, end_byte),
        }
    }

    fn peek_third(&self) -> Option<char> {
        if self.pos + 2 < self.chars.len() {
            Some(self.chars[self.pos + 2].1)
        } else {
            None
        }
    }

    fn skip_whitespace(&mut self) {
        while let Some(c) = self.peek() {
            if c.is_whitespace() {
                self.advance();
            } else {
                break;
            }
        }
    }

    fn read_line_comment(&mut self) -> String {
        let mut s = String::new();
        while let Some(c) = self.peek() {
            if c == '\n' {
                break;
            }
            s.push(c);
            self.advance();
        }
        s
    }

    fn read_block_comment(&mut self) -> String {
        let mut s = String::new();
        self.advance(); // '/'
        self.advance(); // '*'
        s.push_str("/*");
        while let Some(c) = self.peek() {
            if c == '*' && self.peek_next() == Some('/') {
                s.push_str("*/");
                self.advance();
                self.advance();
                break;
            }
            s.push(c);
            self.advance();
        }
        s
    }

    fn read_ident(&mut self) -> String {
        let mut s = String::new();
        while let Some(c) = self.peek() {
            if c.is_ascii_alphanumeric() || c == '_' || c == '\'' || c == '-' {
                s.push(c);
                self.advance();
            } else {
                break;
            }
        }
        s
    }

    fn read_number(&mut self) -> (String, bool) {
        let mut s = String::new();
        let mut is_float = false;
        while let Some(c) = self.peek() {
            if c.is_ascii_digit() {
                s.push(c);
                self.advance();
            } else if c == '.' && !is_float && self.peek_next().map_or(false, |next| next.is_ascii_digit()) {
                is_float = true;
                s.push(c);
                self.advance();
            } else {
                break;
            }
        }
        (s, is_float)
    }

    fn read_path(&mut self) -> String {
        let mut s = String::new();
        while let Some(c) = self.peek() {
            if c.is_ascii_alphanumeric() || c == '_' || c == '.' || c == '/' || c == '-' || c == '~' {
                s.push(c);
                self.advance();
            } else {
                break;
            }
        }
        s
    }

    fn try_read_angle_path(&mut self) -> Option<String> {
        let save_pos = self.pos;
        self.advance(); // '<'
        let mut s = String::from("<");
        let mut found_end = false;
        while let Some(c) = self.peek() {
            if c == '>' {
                s.push('>');
                self.advance();
                found_end = true;
                break;
            } else if c.is_ascii_alphanumeric() || c == '_' || c == '.' || c == '/' || c == '-' {
                s.push(c);
                self.advance();
            } else {
                break;
            }
        }
        if found_end {
            Some(s)
        } else {
            self.pos = save_pos;
            None
        }
    }
}
