#[derive(Debug, Clone, PartialEq)]
pub enum TokenKind {
    Ident(String),
    Int(i64),
    Float(f64),
    StringLit(String),
    Path(String),

    // Keywords
    Let,
    In,
    Rec,
    With,
    If,
    Then,
    Else,
    Assert,
    Inherit,
    Or,

    // Symbols
    LBrace,      // {
    RBrace,      // }
    LParen,      // (
    RParen,      // )
    LBracket,    // [
    RBracket,    // ]
    Colon,       // :
    Semicolon,   // ;
    Comma,       // ,
    Dot,         // .
    Assign,      // =
    At,          // @
    Question,    // ?
    Ellipsis,    // ...

    // Operators
    Plus,        // +
    Minus,       // -
    Mul,         // *
    Div,         // /
    Eq,          // ==
    Neq,         // !=
    Lt,          // <
    Le,          // <=
    Gt,          // >
    Ge,          // >=
    And,         // &&
    OrOp,        // ||
    Not,         // !
    Impl,        // ->
    Update,      // //
    Concat,      // ++

    InterpolStart, // ${
    InterpolEnd,   // }
    StringStart,   // "
    StringEnd,     // "
    IndentedStart, // ''
    IndentedEnd,   // ''

    Comment(String),
    Eof,
}

#[derive(Debug, Clone)]
pub struct Token {
    pub kind: TokenKind,
    pub span: Span,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum StringMode {
    DoubleQuote,
    Indented,
}

pub struct Lexer<'a> {
    src: &'a str,
    chars: Vec<(usize, char)>,
    pos: usize,
    pub skip_comment_lines: Vec<usize>,
    mode_stack: Vec<StringMode>,
    brace_stack: Vec<usize>, // brace depth inside interpolations
}

impl<'a> Lexer<'a> {
    pub fn new(src: &'a str) -> Self {
        let chars: Vec<(usize, char)> = src.char_indices().collect();
        Lexer {
            src,
            chars,
            pos: 0,
            skip_comment_lines: Vec::new(),
            mode_stack: Vec::new(),
            brace_stack: Vec::new(),
        }
    }

    fn peek(&self) -> Option<char> {
        if self.pos < self.chars.len() {
            Some(self.chars[self.pos].1)
        } else {
            None
        }
    }

    fn peek_next(&self) -> Option<char> {
        if self.pos + 1 < self.chars.len() {
            Some(self.chars[self.pos + 1].1)
        } else {
            None
        }
    }

    fn advance(&mut self) -> Option<char> {
        if self.pos < self.chars.len() {
            let c = self.chars[self.pos].1;
            self.pos += 1;
            Some(c)
        } else {
            None
        }
    }

    fn byte_pos(&self) -> usize {
        if self.pos < self.chars.len() {
            self.chars[self.pos].0
        } else {
            self.src.len()
        }
    }

    fn line_col(&self, byte_idx: usize) -> (usize, usize) {
        let mut line = 1;
        let mut col = 1;
        for (i, c) in self.src.char_indices() {
            if i >= byte_idx {
                break;
            }
            if c == '\n' {
                line += 1;
                col = 1;
            } else {
                col += 1;
            }
        }
        (line, col)
    }

    pub fn make_span(&self, start_byte: usize, end_byte: usize) -> Span {
        let (start_line, start_col) = self.line_col(start_byte);
        let (end_line, end_col) = self.line_col(end_byte);
        Span {
            start: start_byte,
            end: end_byte,
            start_line,
            start_col,
            end_line,
            end_col,
        }
    }

    pub fn tokenize_all(&mut self) -> Vec<Token> {
        let mut tokens = Vec::new();
        loop {
            let tok = self.next_token();
            let is_eof = tok.kind == TokenKind::Eof;
            tokens.push(tok);
            if is_eof {
                break;
            }
        }
        tokens
    }

    pub fn next_token(&mut self) -> Token {
        if let Some(&mode) = self.mode_stack.last() {
            let in_interpol = !self.brace_stack.is_empty();
            if !in_interpol {
                return self.read_string_content(mode);
            }
