use analysis::Analyzer;
use cli::parse_cli;
use parser::Parser;
use std::fs;
use std::path::Path;
use std::process::exit;
use walkdir::WalkDir;

fn main() {
    let options = parse_cli();
    let mut files_to_process = Vec::new();

    for path_str in &options.file_paths {
        let path = Path::new(path_str);
        if path.is_file() {
            if !is_excluded(path_str, &options.exclude) {
                files_to_process.push(path_str.clone());
            }
        } else if path.is_dir() {
            let mut entries: Vec<String> = Vec::new();
            for entry in WalkDir::new(path)
                .into_iter()
                .filter_entry(|e| {
                    if !options.hidden {
                        let name = e.file_name().to_string_lossy();
                        if name.starts_with('.') && e.depth() > 0 {
                            return false;
                        }
                    }
                    true
                })
                .filter_map(|e| e.ok())
            {
                let p = entry.path();
                if p.is_file() {
                    let name = p.file_name().map(|n| n.to_string_lossy().to_string()).unwrap_or_default();
                    let matches_ext = name.ends_with(".nix");
                    let is_hidden = name.starts_with('.');

                    if matches_ext && (!is_hidden || options.hidden) {
                        let p_str = p.to_string_lossy().to_string();
                        if !is_excluded(&p_str, &options.exclude) {
                            entries.push(p_str);
                        }
                    }
                }
            }
            entries.sort();
            files_to_process.extend(entries);
        } else {
            // Non-existent file
            eprintln!("Error stating file {}: No such file or directory (os error 2)", path_str);
        }
    }

    let mut found_issues = false;

    for file_path in &files_to_process {
        let src = match fs::read_to_string(file_path) {
            Ok(s) => s,
            Err(e) => {
                eprintln!("Error stating file {}: {}", file_path, e);
                continue;
            }
        };

        let mut parser = Parser::new(&src);
        match parser.parse() {
            Ok(ast) => {
                let skip_lines = parser.skip_lines;
                let analyzer = Analyzer::new(&options, skip_lines);
                let issues = analyzer.analyze(&ast);

                if !issues.is_empty() {
                    found_issues = true;

                    if options.edit {
                        let edited_src = edit::apply_edits(&src, &issues);
                        let _ = fs::write(file_path, edited_src);
                    }

                    if options.output_format == "json" {
                        report::print_json_reports(file_path, &issues, None);
                    } else if !options.quiet {
                        report::print_human_report(file_path, &src, &issues);
                    }
                }
            }
            Err(parse_err) => {
                if options.output_format == "json" {
                    report::print_json_reports(file_path, &[], Some(&parse_err.message));
                } else {
                    eprintln!("Error parsing file {}: {}", file_path, parse_err.message);
                }
            }
        }
    }

    if options.fail && found_issues {
        exit(1);
    }
}

fn is_excluded(path: &str, excludes: &[String]) -> bool {
    let path_p = Path::new(path);
    for exc in excludes {
        let exc_p = Path::new(exc);
        if path_p.starts_with(exc_p) || path == exc {
            return true;
        }
    }
    false
}
EOF"}

