            let s = self.read_ident();
            let end_byte = self.byte_pos();
            let kind = match s.as_str() {
                "let" => TokenKind::Let,
                "in" => TokenKind::In,
                "rec" => TokenKind::Rec,
                "with" => TokenKind::With,
                "if" => TokenKind::If,
                "then" => TokenKind::Then,
                "else" => TokenKind::Else,
                "assert" => TokenKind::Assert,
                "inherit" => TokenKind::Inherit,
                "or" => TokenKind::Or,
                _ => TokenKind::Ident(s),
            };
            return Token {
                kind,
                span: self.make_span(start_byte, end_byte),
            };
