#![allow(dead_code, unused_variables, non_snake_case, unused_mut)]

use crate::analysis::Issue;

pub fn apply_edits(src: &str, issues: &[Issue]) -> String {
    let mut raw_edits: Vec<(usize, usize, String)> = Vec::new();

    for issue in issues {
        if issue.message.starts_with("Unused lambda argument:") {
            let start = issue.span.start;
            let end = issue.span.end;
            let name = &src[start..end];
            if !name.starts_with('_') {
                raw_edits.push((start, end, format!("_{}", name)));
            }
        } else if issue.message.starts_with("Unused let binding:") {
            if let Some(span) = issue.full_span {
                let mut start = span.start;
                let mut end = span.end;

                // Expand to consume leading spaces if whole line
                while start > 0 && (src.as_bytes()[start - 1] == b' ' || src.as_bytes()[start - 1] == b'\t') {
                    start -= 1;
                }
                if start > 0 && src.as_bytes()[start - 1] == b'\n' {
                    start -= 1;
                }
                raw_edits.push((start, end, String::new()));
            }
        } else if issue.message.starts_with("Unused lambda pattern:") {
            if let Some(span) = issue.full_span {
                let mut start = span.start;
                let mut end = span.end;

                // Consume trailing comma and whitespace
                while end < src.len() && (src.as_bytes()[end] == b' ' || src.as_bytes()[end] == b'\t' || src.as_bytes()[end] == b',') {
                    end += 1;
                }
                raw_edits.push((start, end, String::new()));
            }
        }
    }

    // Filter out edits that are nested inside larger removal edits
    let removal_spans: Vec<(usize, usize)> = raw_edits
        .iter()
        .filter(|e| e.2.is_empty())
        .map(|e| (e.0, e.1))
        .collect();

    let mut filtered_edits: Vec<(usize, usize, String)> = Vec::new();
    for edit in raw_edits {
        let is_nested = removal_spans.iter().any(|&(p_start, p_end)| {
            (edit.0 > p_start && edit.1 <= p_end) || (edit.0 >= p_start && edit.1 < p_end)
        });
        if !is_nested {
            filtered_edits.push(edit);
        }
    }

    // Sort edits in reverse byte order
    filtered_edits.sort_by(|a, b| b.0.cmp(&a.0));

    let mut result = src.to_string();
    for (start, end, replacement) in filtered_edits {
        if start <= end && end <= result.len() {
            result.replace_range(start..end, &replacement);
        }
    }

    cleanup_empty_lets(&result)
}

fn cleanup_empty_lets(src: &str) -> String {
    let lines: Vec<&str> = src.lines().collect();
    let mut filtered_lines = Vec::new();
    let mut in_empty_let = false;

    for line in lines {
        let trimmed = line.trim();
        if trimmed == "let" {
            in_empty_let = true;
            continue;
        }
        if in_empty_let && trimmed == "in" {
            in_empty_let = false;
            continue;
        }
        if in_empty_let && !trimmed.is_empty() {
            filtered_lines.push("let");
            filtered_lines.push(line);
            in_empty_let = false;
            continue;
        }
        if !in_empty_let {
            filtered_lines.push(line);
        }
    }

    let mut out = filtered_lines.join("\n");
    if src.ends_with('\n') && !out.ends_with('\n') {
        out.push('\n');
    }
    out
}
